import{_ as e,o as n,c as t,U as p}from"./chunks/framework.e625a6bf.js";const g=JSON.parse('{"title":"推荐一个基于 Spring Boot 4.0 + Java 21 + Spring AI 2.0 的大模型项目！","description":"","frontmatter":{"title":"推荐一个基于 Spring Boot 4.0 + Java 21 + Spring AI 2.0 的大模型项目！","date":"2026/04/26 23:00:36","summary":"大家好，我是 Guide。今年元旦假期，我写了一个大模型项目并完全开源了出来。 短短一个月时间，这个项目目前就已经在 Github 收获了 450+ Star，吸引了多位社区爱好者共同参与完善！ 发布","config":{"show":true,"top":false,"dir":true,"dirTag":["h3","h4","h5"],"tag":["info"],"valine":true,"valineId":null},"password":false,"outline":[3,5]},"headers":[],"relativePath":"views/blog/js/2026-0426-推荐一个基于-Spring-Boot-40--Java-21.md","filePath":"views/blog/js/2026-0426-推荐一个基于-Spring-Boot-40--Java-21.md"}'),s={name:"views/blog/js/2026-0426-推荐一个基于-Spring-Boot-40--Java-21.md"};function r(o,a,i,l,c,h){return n(),t("div",null,[...a[0]||(a[0]=[p(`<h6 id="原文-掘金" tabindex="-1">原文 <a href="https://juejin.cn/post/7601374668961759282" target="_blank" rel="noreferrer">掘金</a> <a class="header-anchor" href="#原文-掘金" aria-label="Permalink to &quot;原文 [掘金](https://juejin.cn/post/7601374668961759282)&quot;">​</a></h6><p>大家好，我是 Guide。今年元旦假期，我写了一个大模型项目并完全开源了出来。</p><p>短短一个月时间，这个项目目前就已经在 Github 收获了450+Star，吸引了多位社区爱好者共同参与完善！</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230057-96f2c47f.awebp" alt=""></p><p>发布之后，得益于大家的共同贡献，我们顺利完成了下面这些事情：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230057-79ce84de.awebp" alt=""></p><p>截止目前，我已经累计处理11个 issue 和6个 pr（完成率100%）。</p><p>并且，我还顺利发布了这个项目的配套教程，从简历写法、面试拷打和核心业务实现都有保姆级教程。</p><h2 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h2><p>这是一个基于 Spring Boot 4.0 + Java 21 + Spring AI 2.0 的 AI 智能面试辅助平台。系统提供三大核心功能：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230058-9e6946d5.awebp" alt="效果展示"></p><p>项目地址：</p><p>完整代码完全免费开源，没有 Pro 版本或者付费版！</p><h2 id="简历写法" tabindex="-1">简历写法 <a class="header-anchor" href="#简历写法" aria-label="Permalink to &quot;简历写法&quot;">​</a></h2><p>如何将《SpringAI 智能面试平台+RAG知识库》实战项目写进简历？我一共提供了五大方向版本任选，精准匹配岗位需求：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230058-2cc7c17a.awebp" alt="《SpringAI 智能面试平台+RAG知识库》简历写法"></p><p>每一条描述都紧扣项目真实逻辑，严格遵守项目介绍规范。不仅教你怎么写，更教你怎么补，例如针对本项目未涉及的“用户认证与鉴权”给出补充建议，教你如何基于 SpringSecurity/Sa-Token 包装主流的认证授权方案。</p><p>并且，我还补充了面试官可深挖的技术难点（如Redis Stream vs 传统消息队列**、**分布式限流的实现细节）以及项目难点与解决方案模板。</p><h2 id="教程概览" tabindex="-1">教程概览 <a class="header-anchor" href="#教程概览" aria-label="Permalink to &quot;教程概览&quot;">​</a></h2><p>带大家看看我写的配套教程，用心程度一切都在文字中！整个项目教程，我手绘了几十张技术配图帮助理解。</p><p>例如，RAG 面试题总结这篇，耗时一周终于完成了第一版，一共3.4 万字，包含35 道高频 RAG 面试题，光校对都进行了三次。而且，这还只是第一版，后续还会继续完善优化！</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230058-4870d677.awebp" alt="RAG 面试题"></p><p>这篇是对应的 RAG 知识库详细开发思路的介绍。</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230059-732e7303.awebp" alt="RAG 知识库详细开发思路"></p><p>不仅教你“如何写出代码”，更教你“为什么这么设计”以及“在企业真实场景中如何应对复杂挑战”。</p><p>刚刚发布一天就收到了好评：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230059-d76e7568.awebp" alt="项目收到的好评"></p><h2 id="配套教程内容安排" tabindex="-1">配套教程内容安排 <a class="header-anchor" href="#配套教程内容安排" aria-label="Permalink to &quot;配套教程内容安排&quot;">​</a></h2><p>这个项目当前实现的功能比较简单，学习门槛极低，但涉及到的知识点比较丰富。通过保姆级教程，我们将从零构建一个融合了LLM 集成、RAG（检索增强生成）、向量数据库、分布式限流及异步处理的完整后端架构。</p><p>无论你是想学习Spring AI的前沿应用，还是需要一个高含金量的简历项目，本项目都将为你提供从基建搭建、业务攻坚到面试话术复盘的全方位指导。</p><p>配套项目教程需要付费（后文/文末有加入方法），但请大家理解，主要是想覆盖一些时间成本。而且，收费和提供的服务相比绝对是超级良心了。这辈子不可能干割韭菜的事！</p><p>内容安排如下（更新进度已过大半）：</p><h3 id="环境搭建" tabindex="-1">环境搭建 <a class="header-anchor" href="#环境搭建" aria-label="Permalink to &quot;环境搭建&quot;">​</a></h3><h3 id="核心功能开发" tabindex="-1">核心功能开发 <a class="header-anchor" href="#核心功能开发" aria-label="Permalink to &quot;核心功能开发&quot;">​</a></h3><h3 id="进阶优化" tabindex="-1">进阶优化 <a class="header-anchor" href="#进阶优化" aria-label="Permalink to &quot;进阶优化&quot;">​</a></h3><h3 id="面试" tabindex="-1">面试 <a class="header-anchor" href="#面试" aria-label="Permalink to &quot;面试&quot;">​</a></h3><h2 id="加入学习" tabindex="-1">加入学习 <a class="header-anchor" href="#加入学习" aria-label="Permalink to &quot;加入学习&quot;">​</a></h2><p>如果你想学习这个项目，或者希望把它作为个人项目经历 / 毕设选题，我整理的这一套教程非常细致：从基础设施搭建、核心业务实现，到最后如何在面试中讲清楚思路与亮点，尽量把容易卡住的地方讲透。</p><p>如果你确实需要更系统的辅导，可以点这里了解详情（教程为付费内容，主要是想覆盖一些时间成本，望理解，感谢支持）：《SpringAI 智能面试平台+RAG 知识库》。</p><h2 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h2><p>提示：架构图采用 draw.io 绘制，导出为 svg 格式，在 Dark 模式下的显示效果会有问题。</p><p>系统采用前后端分离架构，整体分为三层：前端展示层、后端服务层、数据存储层。</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230100-6525a751.awebp" alt="系统架构"></p><p>后端层：</p><p>数据存储层：</p><p>PostgreSQL + pgvector：</p><p>Redis：</p><p>RustFS/MinIO (S3)：原始文件（简历 PDF、知识库文档）</p><p>异步处理流程：</p><p>简历分析、知识库向量化和面试报告生成采用 Redis Stream 异步处理，这里以简历分析和知识库向量化为例介绍一下整体流程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">上传请求 → 保存文件 → 发送消息到Stream→ 立即返回</span></span>
<span class="line"><span style="color:#babed8;">                              ↓</span></span>
<span class="line"><span style="color:#babed8;">                      Consumer 消费消息</span></span>
<span class="line"><span style="color:#babed8;">                              ↓</span></span>
<span class="line"><span style="color:#babed8;">                    执行分析/向量化任务</span></span>
<span class="line"><span style="color:#babed8;">                              ↓</span></span>
<span class="line"><span style="color:#babed8;">                      更新数据库状态</span></span>
<span class="line"><span style="color:#babed8;">                              ↓</span></span>
<span class="line"><span style="color:#babed8;">                   前端轮询获取最新状态</span></span></code></pre></div><p>状态流转：PENDING→PROCESSING→COMPLETED/FAILED</p><p><code>PENDING</code><code>PROCESSING</code><code>COMPLETED</code><code>FAILED</code> 知识库问答处理流程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">知识库问答 → 问题向量化 → pgvector 相似度搜索 → 检索相关文档↓</span></span>
<span class="line"><span style="color:#babed8;">                                构建 Prompt → LLM 生成回答 → SSE 流式返回</span></span></code></pre></div><h2 id="技术栈概览" tabindex="-1">技术栈概览 <a class="header-anchor" href="#技术栈概览" aria-label="Permalink to &quot;技术栈概览&quot;">​</a></h2><h3 id="后端技术" tabindex="-1">后端技术 <a class="header-anchor" href="#后端技术" aria-label="Permalink to &quot;后端技术&quot;">​</a></h3><h3 id="前端技术" tabindex="-1">前端技术 <a class="header-anchor" href="#前端技术" aria-label="Permalink to &quot;前端技术&quot;">​</a></h3><h2 id="技术选型常见问题解答" tabindex="-1">技术选型常见问题解答 <a class="header-anchor" href="#技术选型常见问题解答" aria-label="Permalink to &quot;技术选型常见问题解答&quot;">​</a></h2><p>这里只是简单介绍，后续我会分享文章详细拷打技术选型。</p><h3 id="为什么选择-spring-ai" tabindex="-1">为什么选择 Spring AI？ <a class="header-anchor" href="#为什么选择-spring-ai" aria-label="Permalink to &quot;为什么选择 Spring AI？&quot;">​</a></h3><p>Spring AI 是 Spring 官方推出的 AI 集成框架，提供了统一的 LLM 调用抽象。选择它的原因：</p><p><code>BeanOutputConverter</code></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">// 示例：Spring AI 结构化输出varconverter=newBeanOutputConverter&lt;&gt;(ResumeAnalysisDTO.class);Stringresult=chatClient.prompt()</span></span>
<span class="line"><span style="color:#babed8;">    .system(systemPrompt)</span></span>
<span class="line"><span style="color:#babed8;">    .user(userPrompt + converter.getFormat())</span></span>
<span class="line"><span style="color:#babed8;">    .call()</span></span>
<span class="line"><span style="color:#babed8;">    .content();returnconverter.convert(result);// 直接得到 Java 对象</span></span></code></pre></div><h3 id="数据存储为什么选择-postgresql-pgvector" tabindex="-1">数据存储为什么选择 PostgreSQL + pgvector？ <a class="header-anchor" href="#数据存储为什么选择-postgresql-pgvector" aria-label="Permalink to &quot;数据存储为什么选择 PostgreSQL + pgvector？&quot;">​</a></h3><p>本项目需要同时存储结构化数据（简历、面试记录）和向量数据（文档 Embedding）。方案对比：</p><p>选择 pgvector 的理由：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">-- pgvector 相似度搜索示例SELECTcontent,1-(embedding&lt;=&gt;$1)assimilarityFROMvector_storeWHEREmetadata-&gt;&gt;&#39;category&#39;=&#39;Java&#39;ORDERBYembedding&lt;=&gt;$1LIMIT5;</span></span></code></pre></div><p>为什么不选择 MySQL 搭配向量数据库呢？</p><p>PostgreSQL 最大的优势，也是它在 AI 时代甩开对手的“王牌”，就是其强大的可扩展性。开发者可以在不修改内核的情况下，像“即插即用”一样为数据库安装各种功能强大的插件，这让 PostgreSQL 变成了一个无所不能的“数据瑞士军刀”。</p><p>这种“一站式”解决能力，正是其魅力所在。它意味着许多项目不再需要依赖 Elasticsearch、Milvus 等大量外部中间件，仅凭一个增强版的 PostgreSQL 即可满足多样化需求，从而极大地简化了技术栈，降低了开发和运维的复杂度与成本。</p><p>关于 MySQL 和 PostgreSQL 的详细对比，可以参考我写的这篇文章：MySQL vs PostgreSQL，如何选择？。</p><h3 id="为什么引入-redis" tabindex="-1">为什么引入 Redis？ <a class="header-anchor" href="#为什么引入-redis" aria-label="Permalink to &quot;为什么引入 Redis？&quot;">​</a></h3><p>本项目主要有两个场景用到了 Redis：</p><p><code>ConcurrentHashMap</code> 为什么引入 Redis Stream？为何不选择 Kafka、RabbitMQ 等更成熟的消息队列？</p><p>简历分析、知识库向量化等 AI 任务耗时较长（10-60 秒），不适合同步处理。需要消息队列实现异步解耦。</p><p>选择 Redis Stream 的理由：</p><h3 id="构建工具为什么选择-gradle" tabindex="-1">构建工具为什么选择 Gradle？ <a class="header-anchor" href="#构建工具为什么选择-gradle" aria-label="Permalink to &quot;构建工具为什么选择 Gradle？&quot;">​</a></h3><p>SpringBoot 官方现在用的就是 Gradle，加上国内现在都是 Maven 更多，换个 Gradle 还更新颖一些。</p><p>个人也更喜欢用 Gradle，也写过相关的文章：Gradle 核心概念总结。</p><h3 id="为什么使用-mapstruct" tabindex="-1">为什么使用 MapStruct？ <a class="header-anchor" href="#为什么使用-mapstruct" aria-label="Permalink to &quot;为什么使用 MapStruct？&quot;">​</a></h3><p>项目中有大量 Entity ↔ DTO 转换需求，MapStruct 是编译时代码生成的对象映射框架：</p><h3 id="为什么使用-apache-tika" tabindex="-1">为什么使用 Apache Tika？ <a class="header-anchor" href="#为什么使用-apache-tika" aria-label="Permalink to &quot;为什么使用 Apache Tika？&quot;">​</a></h3><p>系统需要解析多种格式的文档（PDF、Word、TXT），Apache Tika 是 Apache 基金会的文档解析库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">// Tika 解析示例Tikatika=newTika();Stringcontent=tika.parseToString(inputStream);// 自动识别格式并提取文本</span></span></code></pre></div><h3 id="为什么使用-sse-而不是-websocket" tabindex="-1">为什么使用 SSE 而不是 WebSocket？ <a class="header-anchor" href="#为什么使用-sse-而不是-websocket" aria-label="Permalink to &quot;为什么使用 SSE 而不是 WebSocket？&quot;">​</a></h3><p>知识库问答需要流式输出（像 ChatGPT 那样逐字显示），有两种技术选择：</p><p>选择 SSE 的理由：</p><p><code>Flux&lt;ServerSentEvent&lt;String&gt;&gt;</code></p><h3 id="前端为什么选择-react-typescript-tailwind-css" tabindex="-1">前端为什么选择 React + TypeScript + Tailwind CSS？ <a class="header-anchor" href="#前端为什么选择-react-typescript-tailwind-css" aria-label="Permalink to &quot;前端为什么选择 React + TypeScript + Tailwind CSS？&quot;">​</a></h3><h2 id="效果展示" tabindex="-1">效果展示 <a class="header-anchor" href="#效果展示" aria-label="Permalink to &quot;效果展示&quot;">​</a></h2><h3 id="简历与面试" tabindex="-1">简历与面试 <a class="header-anchor" href="#简历与面试" aria-label="Permalink to &quot;简历与面试&quot;">​</a></h3><p>简历库：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230101-5a9acdf9.awebp" alt=""></p><p>简历上传分析：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230101-8ad2f1eb.awebp" alt=""></p><p>简历分析详情：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230102-5eafaf85.awebp" alt=""></p><p>面试记录：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230103-cd7b98e1.awebp" alt=""></p><p>面试详情：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230103-d14a25e8.awebp" alt=""></p><p>模拟面试：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230104-68fea5c9.awebp" alt=""></p><h3 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h3><p>知识库管理：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230104-c8b1e0a7.awebp" alt=""></p><p>问答助手：</p><p><img src="http://cdn.sanghangning.cn/blog/hermes/20260426-230105-c1ab5f2c.awebp" alt=""></p><h2 id="学习本项目你将获得什么" tabindex="-1">学习本项目你将获得什么？ <a class="header-anchor" href="#学习本项目你将获得什么" aria-label="Permalink to &quot;学习本项目你将获得什么？&quot;">​</a></h2><p>本项目采用行业最前沿的 Java 21 + Spring Boot 4.0 技术栈，是市面上首个深度集成 Spring AI 2.0 的全栈实战项目。我们不仅提供高质量的代码，更配套了详尽的架构解析教程。</p><p>项目整体设计遵循“由浅入深”原则。即使你的编程基础尚浅，只需跟随我们的保姆级教程，也能顺利从零搭建出一套生产级别的 AI 大模型应用。</p><h3 id="深度掌握-ai-应用开发的核心范式" tabindex="-1">深度掌握 AI 应用开发的核心范式 <a class="header-anchor" href="#深度掌握-ai-应用开发的核心范式" aria-label="Permalink to &quot;深度掌握 AI 应用开发的核心范式&quot;">​</a></h3><p>本项目是你从传统后端转型 AI 应用开发工程师的最佳敲门砖：</p><p>Spring AI 2.0 工业级实战：深入理解 Spring 官方的 AI 抽象层，掌握如何通过统一的声明式接口对接通义千问、OpenAI 等主流模型。</p><p>Prompt Engineering（提示词工程）深度应用：告别简单的字符串拼接。学习如何构建结构化的 System/User Prompt，并利用 BeanOutputConverter 实现 LLM 输出向 Java 对象的自动化映射，彻底终结繁琐的 JSON 手动解析。</p><p>RAG（检索增强生成）全链路闭环：深度拆解“文档解析 -&gt; 文本分块 -&gt; 向量化 (Embedding) -&gt; 向量数据库存储 -&gt; 相似度检索 -&gt; 上下文增强生成”的完整技术链条。</p><h3 id="现代化的-java-后端架构思维" tabindex="-1">现代化的 Java 后端架构思维 <a class="header-anchor" href="#现代化的-java-后端架构思维" aria-label="Permalink to &quot;现代化的 Java 后端架构思维&quot;">​</a></h3><p>你可以学习到优秀的工程实践：</p><h3 id="务实的数据存储与中间件选型" tabindex="-1">务实的数据存储与中间件选型 <a class="header-anchor" href="#务实的数据存储与中间件选型" aria-label="Permalink to &quot;务实的数据存储与中间件选型&quot;">​</a></h3><p>我们拒绝盲目堆砌中间件，而是教你如何基于业务场景做出“最理智”的选择：</p><h3 id="标准化的工程化交付与部署" tabindex="-1">标准化的工程化交付与部署 <a class="header-anchor" href="#标准化的工程化交付与部署" aria-label="Permalink to &quot;标准化的工程化交付与部署&quot;">​</a></h3><p>Gradle 现代构建体系：摆脱 Maven 的繁琐配置，掌握 Gradle 8.14 及其版本目录 (Version Catalog) 的灵活性，学习如何优雅地管理大型项目依赖。</p><p>生产级容器化部署：通过 Docker Compose 一键搭建包含数据库扩展、缓存、对象存储在内的全套运行环境，理解云原生时代下的基础设施配置规范。</p><h3 id="丝滑的前端工程化与交互体验" tabindex="-1">丝滑的前端工程化与交互体验 <a class="header-anchor" href="#丝滑的前端工程化与交互体验" aria-label="Permalink to &quot;丝滑的前端工程化与交互体验&quot;">​</a></h3><p>对于后端开发者，这更是一次补齐“全栈视野”的绝佳机会：</p><p>SSE (Server-Sent Events) 流式渲染：掌握像 ChatGPT 一样逐字输出回答的底层技术，理解其在单向推送场景下相比 WebSocket 的架构优势。</p><p>响应式 UI 与动效设计：利用 Tailwind CSS 极简构建美观界面，结合 Framer Motion 实现高级交互动效。</p><p>AI 数据可视化：通过 Recharts 将 AI 分析后的简历评分、多维对比以直观的雷达图形式呈现，让数据“会说话”。</p><h2 id="加入学习-1" tabindex="-1">加入学习 <a class="header-anchor" href="#加入学习-1" aria-label="Permalink to &quot;加入学习&quot;">​</a></h2><p>如果你想学习这个项目，或者希望把它作为个人项目经历 / 毕设选题，我整理的这一套教程非常细致：从基础设施搭建、核心业务实现，到最后如何在面试中讲清楚思路与亮点，尽量把容易卡住的地方讲透。</p><p>如果你确实需要更系统的辅导，可以点这里了解详情（教程为付费内容，主要是想覆盖一些时间成本，望理解，感谢支持）：《SpringAI 智能面试平台+RAG 知识库》。</p>`,131)])])}const b=e(s,[["render",r]]);export{g as __pageData,b as default};
